DEMO_SUPERTREND_SETTINGS = [
    (10, 3.0),
    (10, 2.0),
    (10, 1.0),
    (7, 3.0),
    (10, 4.0),
    (21, 1.0),
]

DEMO_TIMEFRAMES = [
    ("30m", 1800),
    ("1h", 3600),
    ("2h", 7200),
    ("4h", 14400),
]

DEMO_HISTORY_DAYS = 45
DEMO_CHUNK_CANDLES = 500


def _demo_fetch_candles(timeframe, candle_seconds):
    """Fetch enough completed candles for the same 45-day history window."""
    try:
        required_seconds = (
            DEMO_HISTORY_DAYS * 24 * 60 * 60
        ) + (ATR_PERIOD * candle_seconds * 3)

        chunk_seconds = (
            DEMO_CHUNK_CANDLES * candle_seconds
        )

        chunk_count = int(
            (required_seconds + chunk_seconds - 1)
            / chunk_seconds
        ) + 1

        end = int(time.time())
        all_rows = []

        for _ in range(chunk_count):
            start = end - chunk_seconds

            response = api.request(
                "GET",
                "/v2/history/candles",
                params={
                    "symbol": SYMBOL,
                    "resolution": timeframe,
                    "start": start,
                    "end": end,
                },
            )

            if not isinstance(response, dict):
                break

            if not response.get("success"):
                break

            result = response.get("result")

            if not isinstance(result, list):
                break

            all_rows.extend(result)
            end = start

        if not all_rows:
            return pd.DataFrame()

        rows = []

        for candle in all_rows:
            try:
                rows.append({
                    "time": int(candle["time"]),
                    "open": float(candle["open"]),
                    "high": float(candle["high"]),
                    "low": float(candle["low"]),
                    "close": float(candle["close"]),
                    "volume": float(candle.get("volume", 0)),
                })
            except Exception:
                continue

        if not rows:
            return pd.DataFrame()

        demo_df = pd.DataFrame(rows)

        demo_df = (
            demo_df
            .drop_duplicates("time")
            .sort_values("time")
            .reset_index(drop=True)
        )

        current_start = (
            int(time.time()) // candle_seconds
        ) * candle_seconds

        demo_df = demo_df[
            demo_df["time"] < current_start
        ].copy()

        demo_df = demo_df.reset_index(drop=True)

        return demo_df

    except Exception:
        return pd.DataFrame()


def _demo_build_signal_history(source_df, atr_period, multiplier):
    """Use the same SuperTrend calculation style as the live engine."""
    if source_df.empty or len(source_df) < atr_period + 5:
        return pd.DataFrame()

    work = source_df.copy()

    prev_close = work["close"].shift(1)

    tr1 = work["high"] - work["low"]
    tr2 = (work["high"] - prev_close).abs()
    tr3 = (work["low"] - prev_close).abs()

    work["TR"] = pd.concat(
        [tr1, tr2, tr3],
        axis=1,
    ).max(axis=1)

    work["ATR"] = float("nan")

    work.loc[atr_period - 1, "ATR"] = (
        work["TR"].iloc[:atr_period].mean()
    )

    for i in range(atr_period, len(work)):
        work.loc[i, "ATR"] = (
            work.loc[i - 1, "ATR"] * (atr_period - 1)
            + work.loc[i, "TR"]
        ) / atr_period

    work["HL2"] = (
        work["high"] + work["low"]
    ) / 2.0

    work["FINAL_UPPER"] = float("nan")
    work["FINAL_LOWER"] = float("nan")
    work["SUPERTREND"] = float("nan")
    work["ST_DIRECTION"] = 0
    work["SIGNAL"] = ""

    prev_final_upper = None
    prev_final_lower = None
    prev_supertrend = None
    prev_direction = 1

    for i in range(len(work)):
        atr = work.loc[i, "ATR"]

        if pd.isna(atr):
            continue

        hl2 = float(work.loc[i, "HL2"])
        close = float(work.loc[i, "close"])

        basic_upper = (
            hl2 + multiplier * float(atr)
        )

        basic_lower = (
            hl2 - multiplier * float(atr)
        )

        if i == atr_period - 1 or prev_final_upper is None:
            final_upper = basic_upper
            final_lower = basic_lower
        else:
            previous_close = float(
                work.loc[i - 1, "close"]
            )

            if (
                basic_upper < prev_final_upper
                or previous_close > prev_final_upper
            ):
                final_upper = basic_upper
            else:
                final_upper = prev_final_upper

            if (
                basic_lower > prev_final_lower
                or previous_close < prev_final_lower
            ):
                final_lower = basic_lower
            else:
                final_lower = prev_final_lower

        work.loc[i, "FINAL_UPPER"] = final_upper
        work.loc[i, "FINAL_LOWER"] = final_lower

        if i == atr_period - 1 or prev_supertrend is None:
            direction = 1
            supertrend = final_upper
        else:
            if prev_supertrend == prev_final_upper:
                if close <= final_upper:
                    direction = 1
                    supertrend = final_upper
                else:
                    direction = -1
                    supertrend = final_lower
            else:
                if close >= final_lower:
                    direction = -1
                    supertrend = final_lower
                else:
                    direction = 1
                    supertrend = final_upper

        work.loc[i, "ST_DIRECTION"] = direction
        work.loc[i, "SUPERTREND"] = supertrend

        if i > 0 and prev_direction != direction:
            if direction == -1:
                work.loc[i, "SIGNAL"] = "BUY"
            elif direction == 1:
                work.loc[i, "SIGNAL"] = "SELL"

        prev_final_upper = final_upper
        prev_final_lower = final_lower
        prev_supertrend = supertrend
        prev_direction = direction

    signal_data = work[
        work["SIGNAL"].isin(["BUY", "SELL"])
    ].copy()

    cutoff = int(time.time()) - (
        DEMO_HISTORY_DAYS * 24 * 60 * 60
    )

    signal_data = signal_data[
        signal_data["time"].astype(int) >= cutoff
    ].copy()

    return (
        signal_data
        .sort_values("time")
        .reset_index(drop=True)
    )


