# ============================================================
# PART 4/4 ADD-ON — ENTRY / TARGET / RE-ENTRY TRACKER
# Display-only block placed BELOW the existing chart.
# IMPORTANT: this tracker follows the SAME fixed-level client IDs used by
# the live grid engine above. It never matches a target/re-entry by price alone.
# Each level owns its own independent ENTRY -> TARGET -> RE-ENTRY cycle.
# ============================================================

def _tracker_order_price(order):
    try:
        return float(_grid_price(order))
    except Exception:
        return None

def _tracker_order_qty_btc(order):
    try:
        return float(_grid_contracts(order)) * CONTRACT_BTC
    except Exception:
        return 0.0

def _tracker_epoch(order):
    try:
        return float(_closed_order_epoch(order))
    except Exception:
        return 0.0

def _tracker_role(order):
    cid = str(order.get("client_order_id", ""))
    if "GRID_INITIAL_" in cid: return "INITIAL"
    if "_ENT_" in cid: return "ENTRY"
    if "_TGT_" in cid: return "TARGET"
    if "_RE_" in cid: return "REENTRY"
    return ""

def _tracker_has_label(orders, label):
    return any(
        _grid_order_id(o) and _grid_order_matches_label(o, label)
        for o in orders
    )

def _tracker_filled_for_label(orders, label):
    return [
        o for o in orders
        if _grid_order_id(o) and _grid_order_matches_label(o, label)
    ]

_tracker_open = [o for o in (_grid_active_bot_orders(grid_open_orders) if grid_open_ok else [])]
_tracker_closed = [o for o in (grid_closed_orders if grid_closed_ok else [])
                   if _grid_is_bot(o) and str(o.get("state", "")).lower() == "filled"]
_tracker_chains = []

if grid_direction:
    _target_side_text = "SELL" if grid_direction == "BUY" else "BUY"
    _reentry_side_text = "BUY" if grid_direction == "BUY" else "SELL"

    # Same cycle-specific labels as the live engine.
    for _level_no, _level_price in outer_levels:
        _level_no = int(_level_no)
        _level_price = float(_level_price)

        _entry_label = f"ENTRY_{_cycle_tag}_L{_level_no}"
        _target_label = f"TARGET_{_cycle_tag}_L{_level_no}"
        _reentry_label = f"REENTRY_{_cycle_tag}_L{_level_no}"

        _target_price = _target_from_original_level(
            _level_no,
            grid_direction
        )

        _entry_open = _tracker_has_label(_tracker_open, _entry_label)
        _entry_filled = _tracker_filled_for_label(
            _tracker_closed,
            _entry_label
        )
        _target_open = _tracker_has_label(_tracker_open, _target_label)
        _target_filled = _tracker_filled_for_label(
            _tracker_closed,
            _target_label
        )
        _reentry_open = _tracker_has_label(_tracker_open, _reentry_label)
        _reentry_filled = _tracker_filled_for_label(
            _tracker_closed,
            _reentry_label
        )

        if _entry_filled:
            _entry_status = "FILLED"
        elif _entry_open:
            _entry_status = "LIMIT PENDING"
        else:
            _entry_status = "WAITING"

        if _target_filled:
            _target_status = "TARGET HIT"
        elif _target_open:
            _target_status = "TARGET PENDING"
        else:
            _target_status = "WAITING"

        if _reentry_filled:
            _reentry_status = "RE-ENTRY FILLED"
        elif _reentry_open:
            _reentry_status = "RE-ENTRY PENDING"
        else:
            _reentry_status = "WAITING"

        _tracker_chains.append({
            "level_no": _level_no,
            "entry_price": _level_price,
            "entry_qty": GRID_CHUNK_BTC,
            "entry_status": _entry_status,
            "target_price": _target_price,
            "target_status": _target_status,
            "reentry_status": _reentry_status,
            "target_count": len(_target_filled),
            "reentry_count": len(_reentry_filled),
        })

_tracker_html = [
    '<div style="background:#0b0e11;color:#e5e7eb;padding:14px 8px 18px 8px;font-family:Arial,sans-serif;">',
    '<div style="font-size:21px;font-weight:800;margin-bottom:5px;">📋 14-LEVEL ENTRY / TARGET / RE-ENTRY</div>',
    f'<div style="font-size:13px;color:#9ca3af;margin-bottom:12px;">'
    f'{grid_direction} • L1 = ATR {show_price(grid_atr_line)} • '
    f'Step = {GRID_STEP} • प्रत्येक level का target उसी fixed level से</div>'
]

if not _tracker_chains:
    _tracker_html.append(
        '<div style="padding:16px;border:1px solid #30363d;'
        'border-radius:10px;background:#11161c;">'
        'No active SuperTrend grid cycle found.</div>'
    )
else:
    _tracker_html.append(
        '<div style="overflow-x:auto;">'
        '<table style="width:100%;border-collapse:collapse;min-width:780px;'
        'font-size:13px;">'
        '<thead><tr style="background:#151b22;color:#cbd5e1;">'
        '<th style="padding:9px;text-align:left;">LEVEL</th>'
        '<th style="padding:9px;text-align:right;">ENTRY</th>'
        '<th style="padding:9px;text-align:center;">ENTRY STATUS</th>'
        '<th style="padding:9px;text-align:right;">TARGET</th>'
        '<th style="padding:9px;text-align:center;">TARGET STATUS</th>'
        '<th style="padding:9px;text-align:center;">RE-ENTRY</th>'
        '</tr></thead><tbody>'
    )

    for _c in _tracker_chains:
        _tracker_html.append(
            f'<tr style="border-bottom:1px solid #252a31;">'
            f'<td style="padding:9px;font-weight:800;">L{_c["level_no"]}</td>'
            f'<td style="padding:9px;text-align:right;">'
            f'₹{_c["entry_price"]:,.2f}<br>'
            f'<span style="color:#9ca3af;">{_c["entry_qty"]:.3f} BTC</span></td>'
            f'<td style="padding:9px;text-align:center;font-weight:800;">'
            f'{_c["entry_status"]}</td>'
            f'<td style="padding:9px;text-align:right;">'
            f'₹{_c["target_price"]:,.2f}<br>'
            f'<span style="color:#9ca3af;">{_target_side_text}</span></td>'
            f'<td style="padding:9px;text-align:center;font-weight:800;">'
            f'{_c["target_status"]}<br>'
            f'<span style="color:#9ca3af;">Hits: {_c["target_count"]}</span></td>'
            f'<td style="padding:9px;text-align:center;font-weight:800;">'
            f'{_c["reentry_status"]}<br>'
            f'<span style="color:#9ca3af;">Count: {_c["reentry_count"]}</span></td>'
            f'</tr>'
        )

    _tracker_html.append('</tbody></table></div>')

components.html(
    "".join(_tracker_html),
    height=620,
    scrolling=True
)


time.sleep(REFRESH_SECONDS)
st.rerun()

